const chatInput = $('Admin Chat Trigger').first().json.chatInput;
const inquiries = $('Read Inquiries Data').all().map(r => ({
  name: r.json['Client Name'],
  category: r.json['Category'],
  intent: r.json['Intent'],
  urgency: r.json['Urgency'],
  buyingIntent: r.json['Buying Intent'],
  status: r.json['Status'],
  summary: r.json['Summary'],
  timestamp: r.json['Timestamp']
}));

const complaints = $('Read Complaints Data').all().map(r => ({
  ticketId: r.json['Ticket ID'] || r.json[' Ticket ID'],
  clientName: r.json['Client Name'],
  category: r.json['Category'],
  urgency: r.json['Urgency'],
  status: r.json['Status'],
  summary: r.json['AI Summary'],
  timestamp: r.json['Timestamp']
}));

// Build summary stats
const totalInquiries = inquiries.length;
const hotLeads = inquiries.filter(i => i.buyingIntent === 'HIGH').length;
const openComplaints = complaints.filter(c => c.status === 'OPEN').length;
const criticalComplaints = complaints.filter(c => c.urgency === 'CRITICAL' && c.status === 'OPEN').length;
const coldLeads = inquiries.filter(i => i.status === 'COLD').length;
const followedUp = inquiries.filter(i => i.status === 'FOLLOWED_UP').length;

const contextSummary = `
BUSINESS DATA SUMMARY:
- Total Inquiries: ${totalInquiries}
- Hot Leads (HIGH buying intent): ${hotLeads}
- Cold Leads: ${coldLeads}
- Followed Up: ${followedUp}
- Open Complaints: ${openComplaints}
- Critical Open Complaints: ${criticalComplaints}

RECENT INQUIRIES (last 10):
${JSON.stringify(inquiries.slice(-10), null, 2)}

OPEN COMPLAINTS:
${JSON.stringify(complaints.filter(c => c.status === 'OPEN').slice(-10), null, 2)}
`;

return [{
  json: {
    chatInput,
    contextSummary,
    requestBody: {
      model: "llama-3.3-70b-versatile",
      max_tokens: 1000,
      temperature: 0.3,
      messages: [
        {
          role: "system",
          content: "You are PRONTA Admin AI Assistant for PRONTA (Private) Limited, a Pakistani industrial supplier. You have access to real business data. Answer questions about inquiries, complaints, leads, and business performance. Be concise, professional, and data-driven. Always provide specific numbers when available. Format responses clearly with emojis for readability."
        },
        {
          role: "user",
          content: `Director Question: ${chatInput}\n\n${contextSummary}`
        }
      ]
    }
  }
}];
